CREATE TABLE IF NOT EXISTS algo_flow_evaluations (id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL, correlation_id TEXT NOT NULL, mode TEXT NOT NULL, broker TEXT NOT NULL, current_stage TEXT NOT NULL, final_decision TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS gate_results (id TEXT PRIMARY KEY, evaluation_id TEXT NOT NULL REFERENCES algo_flow_evaluations(id), stage TEXT NOT NULL, observed_value JSONB, threshold JSONB, passed BOOLEAN NOT NULL, evidence JSONB, reason TEXT, evaluated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS groww_broker_connections (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, credential_reference TEXT NOT NULL, api_version TEXT NOT NULL, permissions JSONB NOT NULL, health TEXT NOT NULL, compliance_approval BOOLEAN NOT NULL DEFAULT false, checked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS protection_plans (id TEXT PRIMARY KEY, position_id TEXT NOT NULL, protection_type TEXT NOT NULL, quantity INTEGER NOT NULL, target_leg JSONB, stop_loss_leg JSONB, provider_reference TEXT, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS news_outcomes (event_id TEXT NOT NULL, prediction_id TEXT NOT NULL, horizon TEXT NOT NULL, predicted_direction TEXT NOT NULL, predicted_impact NUMERIC NOT NULL, confidence NUMERIC NOT NULL, realized_move NUMERIC, accuracy NUMERIC, evaluated_at TIMESTAMPTZ, PRIMARY KEY (event_id, prediction_id, horizon));
CREATE TABLE IF NOT EXISTS promotion_evidence (strategy_version TEXT PRIMARY KEY, out_of_sample BOOLEAN NOT NULL DEFAULT false, walk_forward BOOLEAN NOT NULL DEFAULT false, paper_validated BOOLEAN NOT NULL DEFAULT false, assisted_approved BOOLEAN NOT NULL DEFAULT false, capped_live BOOLEAN NOT NULL DEFAULT false, consent BOOLEAN NOT NULL DEFAULT false, compliance_approved BOOLEAN NOT NULL DEFAULT false, reviewed_at TIMESTAMPTZ);